changeSet.sql:
ALTER TABLE purchase_order
    ADD COLUMN ponumber_base varchar(255)
    GENERATED ALWAYS AS (regexp_replace(ponumber, '-V[0-9]+$', '')) STORED;

CREATE INDEX IF NOT EXISTS idx_purchase_order_ponumber_base
    ON purchase_order (ponumber_base);

CREATE INDEX IF NOT EXISTS idx_purchase_order_contractnumber_ponumber_base
    ON purchase_order (contractnumber, ponumber_base);
